public class DaemonThreadDemonstration {
    public static void main(String[] args) throws InterruptedException {
        Thread backgroundMonitor = new Thread(() -> {
            while (true) {
                try {
                    System.out.println("Background monitor heartbeat...");
                    Thread.sleep(500);
                } catch (InterruptedException e) {
                    System.out.println("Monitor interrupted.");
                    break;
                }
            }
        });

        // Must be set to true BEFORE calling start()
        backgroundMonitor.setDaemon(true);
        backgroundMonitor.start();

        System.out.println("Main user thread doing critical work...");
        Thread.sleep(1500);
        System.out.println("Main user thread terminating now. JVM will exit immediately.");
    }
}
